// Source-stage/fused algorithms shared by native and Wasm.
fn quot(a:u32,b:u32,z:u32)->u32{if b==0{z}else{a/b}}
fn rem(a:u32,b:u32,z:u32)->u32{if b==0{z}else{a%b}}
#[no_mangle]pub extern "C" fn bench_alloc(n:usize)->*mut u32{let mut v=vec![0;n];let p=v.as_mut_ptr();std::mem::forget(v);p}
#[no_mangle]pub unsafe extern "C" fn bench_free(p:*mut u32,n:usize){drop(Vec::from_raw_parts(p,n,n));}
fn calibrate(x:u32,seed:u32,k:u32)->u32{(if (x<seed){((x).wrapping_add(7u32)).wrapping_mul(k)}else{(x).wrapping_sub(seed)})}fn normalize(x:u32,seed:u32,k:u32)->u32{(if (x>k){(x).wrapping_sub(k)}else{(x).wrapping_add(seed)})}fn step_word(x:u32,a:u32,seed:u32,k:u32)->u32{(if (a<seed){(x).wrapping_add((a).wrapping_mul(k))}else{(x).wrapping_sub(a)})}fn pair_word(a:u32,b:u32,seed:u32,k:u32)->u32{let a=calibrate(a,seed,k);let b=normalize(b,seed,k);(if (a<b){(a).wrapping_add((b).wrapping_mul(k))}else{(a).wrapping_sub((b).wrapping_mul(k))})}fn accept_list(xs:&[u32],seed:u32,k:u32)->Vec<u32>{xs.iter().copied().filter(|&x|(rem(x,seed,0u32)<k)).collect()}
pub fn bench_scalar(case:u32,xs:&[u32],ys:&[u32],seed:u32,k:u32)->u64{match case{
4=>{let mut a=seed;for &x in xs.iter().rev(){a=step_word(calibrate(x,seed,k),a,seed,k);}a as u64},
_=>panic!("non-scalar case")}}
#[no_mangle]pub unsafe extern "C" fn bench_eval(case:u32,xp:*const u32,xn:usize,yp:*const u32,yn:usize,seed:u32,k:u32,out:*mut u32)->usize{let xs=std::slice::from_raw_parts(xp,xn);let ys=std::slice::from_raw_parts(yp,yn);match case{
0=>{let mut paired=Vec::new();for j in 0..xs.len().min(ys.len()){let a=xs[j];let b=ys[j];paired.push((if (a<seed){(a).wrapping_add((b).wrapping_mul(k))}else{(a).wrapping_sub(b)}));}let mapped:Vec<u32>=paired.iter().copied().enumerate().map(|(j,v)|{let x=xs[j];(if (v<seed){(v).wrapping_add((x).wrapping_mul(k))}else{(v).wrapping_sub(x)})}).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
1=>{let mut paired=Vec::new();for j in 0..xs.len().min(ys.len()){let a=xs[j];let b=ys[j];paired.push((if (a<seed){(a).wrapping_add((b).wrapping_mul(k))}else{(a).wrapping_sub(b)}));}let mapped:Vec<u32>=paired.iter().copied().enumerate().map(|(j,v)|{let x=ys[j];(if (v<seed){(v).wrapping_add((x).wrapping_mul(k))}else{(v).wrapping_sub(x)})}).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
2=>{let mapped:Vec<u32>=xs.iter().copied().map(|x|calibrate(x,seed,k)).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
3=>{let mapped:Vec<u32>=xs.iter().copied().enumerate().map(|(i,x)|if i%2==0{normalize(calibrate(x,seed,k),seed,k)}else{calibrate(x,seed,k)}).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
4=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
5=>{let accepted=accept_list(xs,seed,k);let mapped:Vec<u32>=accepted.iter().copied().map(|x|normalize(calibrate(x,seed,k),seed,k)).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
6=>{let mapped:Vec<u32>=xs.iter().copied().zip(ys.iter().copied()).map(|(a,b)|pair_word(a,b,seed,k)).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
7=>{let mapped:Vec<u32>=xs.iter().copied().map(|x|{let mut v=x.wrapping_add(seed);v=rem(v.wrapping_mul(k.wrapping_add(1u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(3u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(5u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(7u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(9u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(11u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(13u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(15u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(17u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(19u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(21u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(23u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(25u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(27u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(29u32)).wrapping_add(x),4294967291u32,seed);v=rem(v.wrapping_mul(k.wrapping_add(31u32)).wrapping_add(x),4294967291u32,seed);v}).collect();for(j,&v)in mapped.iter().enumerate(){*out.add(j)=v;}mapped.len()},
_=>panic!("unknown case")}}
